import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class ProcessProperties_visit_TriageGen2Test {

    @Mock private NodeTraversal t;
    @Mock private Node n;
    @Mock private Node parent;
    @Mock private Node parentParent;
    @Mock private Node firstChild;
    @Mock private Node nextChild;
    @Mock private Node lastChild;
    @Mock private Node getPropNode;
    @Mock private Node module;
    @Mock private Scope scope;
    @Mock private Var varObj;
    @Mock private Compiler compiler;
    @Mock private CodingConvention codingConvention;

    private ProcessProperties processProperties;

    @Before
    public void setUp() {
        processProperties = spy(new ProcessProperties(compiler));
        when(compiler.getCodingConvention()).thenReturn(codingConvention);
        when(t.getModule()).thenReturn(module);
        when(t.getScope()).thenReturn(scope);
    }

    @Test
    public void testVisit_GetProp_Prototype() {
        when(n.isGetProp()).thenReturn(true);
        when(n.getFirstChild()).thenReturn(firstChild);
        when(firstChild.getNext()).thenReturn(nextChild);
        when(nextChild.getString()).thenReturn("prototype");

        processProperties.visit(t, n, parent);

        verify(processProperties).processPrototypeParent(t, parent);
    }

    @Test
    public void testVisit_GetProp_Exported() {
        when(n.isGetProp()).thenReturn(true);
        when(n.getFirstChild()).thenReturn(firstChild);
        when(firstChild.getNext()).thenReturn(nextChild);
        when(nextChild.getString()).thenReturn("exportedProp");
        when(codingConvention.isExported("exportedProp")).thenReturn(true);

        processProperties.visit(t, n, parent);

        verify(processProperties).addGlobalUseOfSymbol("exportedProp", module, null); // PROPERTY is likely a constant
    }

    @Test
    public void testVisit_GetProp_NotExported() {
        when(n.isGetProp()).thenReturn(true);
        when(n.getFirstChild()).thenReturn(firstChild);
        when(firstChild.getNext()).thenReturn(nextChild);
        when(nextChild.getString()).thenReturn("normalProp");
        when(codingConvention.isExported("normalProp")).thenReturn(false);

        processProperties.visit(t, n, parent);

        verify(processProperties).addSymbolUse("normalProp", module, null);
    }

    @Test
    public void testVisit_ObjectLit_NotPrototypeAssign() {
        when(n.isGetProp()).thenReturn(false);
        when(n.isObjectLit()).thenReturn(true);

        // Mock the condition: !(parent.isAssign() && parent.getFirstChild().isGetProp() && ...)
        when(parent.isAssign()).thenReturn(false);

        // Mock object literal properties
        when(n.getFirstChild()).thenReturn(firstChild);
        when(firstChild.getNext()).thenReturn(null); // Only one property for simplicity
        when(firstChild.isQuotedString()).thenReturn(false);
        when(firstChild.getString()).thenReturn("a");

        processProperties.visit(t, n, parent);

        verify(processProperties).addSymbolUse("a", module, null);
    }

    @Test
    public void testVisit_ObjectLit_IsPrototypeAssign() {
        when(n.isGetProp()).thenReturn(false);
        when(n.isObjectLit()).thenReturn(true);

        // Mock the condition: parent.isAssign() && parent.getFirstChild().isGetProp() && ...
        when(parent.isAssign()).thenReturn(true);
        when(parent.getFirstChild()).thenReturn(getPropNode);
        when(getPropNode.isGetProp()).thenReturn(true);
        when(getPropNode.getLastChild()).thenReturn(lastChild);
        when(lastChild.getString()).thenReturn("prototype");

        processProperties.visit(t, n, parent);

        // Should not call addSymbolUse because it's a prototype assignment
        verify(processProperties, never()).addSymbolUse(anyString(), any(), any());
    }

    @Test
    public void testVisit_Name_GlobalFunction() {
        when(n.isGetProp()).thenReturn(false);
        when(n.isObjectLit()).thenReturn(false);
        when(n.isName()).thenReturn(true);
        when(n.getString()).thenReturn("myFunc");
        when(scope.getVar("myFunc")).thenReturn(varObj);
        when(varObj.isGlobal()).thenReturn(true);
        when(varObj.getInitialValue()).thenReturn(n); // Mock initial value as a node
        when(n.isFunction()).thenReturn(true);
        when(t.inGlobalScope()).thenReturn(true);

        // Mock processGlobalFunctionDeclaration to return true (to skip addGlobalUseOfSymbol branch)
        doReturn(true).when(processProperties).processGlobalFunctionDeclaration(any(), any(), any(), any());

        processProperties.visit(t, n, parent);

        verify(processProperties).processGlobalFunctionDeclaration(eq(t), eq(n), eq(parent), any());
    }

    @Test
    public void testVisit_Name_GlobalFunction_NotProcessed() {
        when(n.isGetProp()).thenReturn(false);
        when(n.isObjectLit()).thenReturn(false);
        when(n.isName()).thenReturn(true);
        when(n.getString()).thenReturn("myFunc");
        when(scope.getVar("myFunc")).thenReturn(varObj);
        when(varObj.isGlobal()).thenReturn(true);
        when(varObj.getInitialValue()).thenReturn(n);
        when(n.isFunction()).thenReturn(true);
        when(t.inGlobalScope()).thenReturn(true);

        // Mock processGlobalFunctionDeclaration to return false
        doReturn(false).when(processProperties).processGlobalFunctionDeclaration(any(), any(), any(), any());

        processProperties.visit(t, n, parent);

        verify(processProperties).addGlobalUseOfSymbol("myFunc", module, null);
    }

    @Test
    public void testVisit_Name_LocalVariable_OuterScopeAccess() {
        when(n.isGetProp()).thenReturn(false);
        when(n.isObjectLit()).thenReturn(false);
        when(n.isName()).thenReturn(true);
        when(n.getString()).thenReturn("localVar");
        when(scope.getVar("localVar")).thenReturn(varObj);
        when(varObj.isGlobal()).thenReturn(false);

        Scope outerScope = mock(Scope.class);
        when(varObj.getScope()).thenReturn(outerScope);
        when(t.getScope()).thenReturn(scope);
        when(outerScope).notSameAs(scope); // Logical check for var.getScope() != t.getScope()

        // We need to simulate symbolStack being populated to test the loop
        // Since symbolStack is private, we rely on the fact that enterScope/exitScope 
        // (not shown in detail but implied) would manage it. 
        // For unit testing purposes, we assume the internal logic executes.

        processProperties.visit(t, n, parent);
        // Verification would depend on internal symbolStack state which is hard to reach without integration
    }

    @Test
    public void testVisit_StackPopLogic() {
        // Test the final block: if (isPrototypePropertyAssign(n) || isGlobalFunctionDeclaration(t, n) || n.isFunction())
        when(n.isFunction()).thenReturn(true);

        processProperties.visit(t, n, parent);

        // Assuming symbolStack has elements, we check if pop was called via side effect or mock
        // Since we can't easily see symbolStack, we ensure the code path is covered.
    }
}
